// a_n = 1 / 2^n + 1 / 3^n, n starts at 1.
export @Sum(epsilon:Number)->Number {
  if epsilon<=0 { throw "epsilon must be positive"; }
  let mut half=0.5; let mut third=1/3; let mut total=0;
  while half+third>epsilon {
    total=total+half+third;
    half=half/2; third=third/3;
  }
  return total;
}
